      "keystrokes": "cat > /app/solve.py << 'EOF'\nimport numpy as np\n\nV = 150000\np = np.full(V, 10.0 ** 10.0 / V)\n\nr = np.log10(p) + np.log10(V)\nprint('sum', p.sum())\nprint('fwd', np.sum(p * r))\nprint('bwd', -np.mean(r))\nnp.save('/app/dist.npy', p)\nEOF\n",
      "duration": 0.5
    },
    {
      "keystrokes": "python3 /app/solve.py\n",
      "duration": 3.0
    }
  ]
}

